package pe.edu.upeu.bomerp;
import org.springframework.web.bind.annotation.*;import org.springframework.security.access.prepost.PreAuthorize;import lombok.RequiredArgsConstructor;import java.util.*;import java.math.BigDecimal;import java.time.LocalDate;
@RestController @RequestMapping("/api/reportes") @RequiredArgsConstructor public class ReportesController {
private final pe.edu.upeu.bomerp.produccion.service.OrdenProduccionService produccion;private final pe.edu.upeu.bomerp.inventario.repository.LoteRepository lotes;
@GetMapping("/produccion") @PreAuthorize("@acceso.permite(authentication,'PRODUCCION')") public List<Map<String,Object>> produccion(@RequestParam(required=false)LocalDate desde,@RequestParam(required=false)LocalDate hasta,@RequestParam(defaultValue="")String estado){if(desde!=null&&hasta!=null&&desde.isAfter(hasta))throw new IllegalArgumentException("Rango de fechas inválido");return produccion.listar().stream().filter(o->(estado.isEmpty()||o.getEstado().name().equals(estado))&&(desde==null||!o.getFechaPlanificada().toLocalDate().isBefore(desde))&&(hasta==null||!o.getFechaPlanificada().toLocalDate().isAfter(hasta))).map(o->{Map<String,Object> r=new LinkedHashMap<>();r.put("id",o.getId());r.put("formula",o.getFormula().getNombre());r.put("estado",o.getEstado());r.put("planificado",o.getCantidadPlanificada());r.put("producido",o.getCantidadReal()==null?BigDecimal.ZERO:o.getCantidadReal());r.put("insumos",o.getFormula().getDetalles().stream().map(d->{var esperado=d.getCantidadPorUnidad().multiply(o.getCantidadPlanificada());var real=o.getConsumos().stream().filter(c->c.getCodigoArticulo().equals(d.getCodigoArticulo())).map(c->c.getCantidadConsumida()).reduce(BigDecimal.ZERO,BigDecimal::add);return Map.of("articulo",d.getCodigoArticulo(),"unidad",d.getUnidadMedida(),"planificado",esperado,"real",real,"desviacion",real.subtract(esperado));}).toList());return r;}).toList();}
@GetMapping("/stock") @PreAuthorize("@acceso.permite(authentication,'INVENTARIO') or @acceso.permite(authentication,'PRODUCCION') or @acceso.permite(authentication,'VENTAS')") public java.util.List<pe.edu.upeu.bomerp.inventario.model.Lote> stock(){return lotes.findAll();}
}
